/*
 * config_frames_test -- the whole machine held to MAME, with no ROM: the baked
 * CONFIG client boots on the FujiNet cartridge, link down, and its frames must
 * hash as MAME's did for the same set-up (config_golden.h, generated by
 * tools/ab/config_golden.py from a MAME run). The Channel F has no BIOS and no
 * character ROM, so nothing needs importing: CONFIG's pictures come from the
 * UVI's glyph table, the palette and the character RAM, drawn line by line from
 * the 2650's writes, so a match covers the 2650, the line timer, the UVI's
 * renderer and the cartridge's flat-image serving and mailbox, all at once --
 * frame for frame from the very first frame.
 *
 * Copyright (C) 2026 Thomas Cherryhomes
 * SPDX-License-Identifier: GPL-3.0-or-later
 */

#include <stdio.h>
#include <string.h>

#include "chf_internal.h"
#include "config_golden.h"

static unsigned long long fnv64(const uint32_t *px, size_t n)
{
    unsigned long long h = 14695981039346656037ull;

    for (size_t i = 0; i < n; i++) {
        h ^= px[i] & 0xffffffu;
        h *= 1099511628211ull;
    }
    return h;
}

int main(void)
{
    static chf_machine_t m;
    chf_machine_opts_t mo;
    chf_fujinet_t *fj;
    char why[160];
    int failures = 0, next = 0, last = 0;
    const int n = (int)(sizeof k_config_golden / sizeof k_config_golden[0]);

    for (int i = 0; i < n; i++)
        if (k_config_golden[i].frame > last)
            last = k_config_golden[i].frame;
    fj = chf_fujinet_create();
    if (!fj || chf_fujinet_power_on(fj, NULL, 0, "", true, why, sizeof why) != 0) {
        fprintf(stderr, "config_frames: cannot power on the cartridge: %s\n", why);
        return 1;
    }
    memset(&mo, 0, sizeof mo);
    mo.machine = CHF_MACHINE_ARCADIA;
    mo.cart = chf_fujinet_cart(fj);
    mo.fujinet = fj;
    chf_machine_init(&m, &mo);

    for (int f = 0; f <= last; f++) {
        chf_machine_run_frame(&m);
        while (next < n && k_config_golden[next].frame == f) {
            unsigned long long h = fnv64(m.fb, CHF_FB_WIDTH * CHF_FB_HEIGHT);

            if (h == k_config_golden[next].hash) {
                printf("ok: frame %d matches MAME (%016llx)\n", f, h);
            } else {
                printf("FAIL: frame %d is %016llx, MAME's is %016llx\n", f, h,
                       k_config_golden[next].hash);
                failures++;
            }
            next++;
        }
    }
    chf_fujinet_destroy(fj);
    printf("%d failure(s)\n", failures);
    return failures ? 1 : 0;
}
